/** One paired-pad economy with actual asynchronous withdrawal, caught rollback and exact retry. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopyRuntimeChecks {
    private static final BlockPos ROOT=new BlockPos(phase().isEmpty()?14:16,120,8),INPUT=ROOT.east(),OUTPUT=ROOT.west(),SOURCE=INPUT.above(),TARGET=OUTPUT.above(),SUPPLY=ROOT.south();
    private static final UUID ACTOR=new UUID(0,0x436f7079);
    private static ServerLevel world;private static NativeCopyControllerEntity root;private static Actor actor;private static CompoundTag source,beforeSupply;
    private static int ticks,checks,stage,stageTick,armed,caught;private static long idleScans,idlePackets;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel world){super(world,new com.mojang.authlib.GameProfile(ACTOR,"CopyRuntimeFixture"));}}
    private static String phase(){return System.getProperty("vandorlabs.copyPhase","");}
    private static boolean enabled(){return Boolean.getBoolean("vandorlabs.copyRuntimeChecks") && !Boolean.getBoolean("vandorlabs.copyPairedChestCheck") && !Boolean.getBoolean("vandorlabs.copyObserversCheck") && !Boolean.getBoolean("vandorlabs.copyScreensCheck");}
    private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Copy stage="+stage+" tick="+ticks+" busy="+(root!=null&&root.busy())+" status="+(root==null?"absent":root.status())+" error="+(root==null?"absent":root.error())+": "+message);}
    private static ChestBlockEntity chest(BlockPos pos){return (ChestBlockEntity)world.getBlockEntity(pos);}
    private static ItemStack gold(int count){var stack=new ItemStack(Items.GOLD_INGOT,count);stack.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Copy receipt gold"));var tag=new CompoundTag();tag.putString("Receipt","copy-exact-components");stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));return stack;}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();if(phase().equals("read")){read(event);return;}for(int x=ROOT.getX()-4;x<=ROOT.getX()+4;x++)for(int z=ROOT.getZ()-2;z<=ROOT.getZ()+3;z++){world.setChunkForced(x>>4,z>>4,true);world.getChunkAt(new BlockPos(x,120,z));}world.setBlock(ROOT,NativeCopyBindings.BLOCK.defaultBlockState(),3);world.setBlock(INPUT,NativeSurfaceBindings.BLOCK.defaultBlockState(),3);world.setBlock(OUTPUT,NativeSurfaceBindings.BLOCK.defaultBlockState(),3);world.setBlock(SOURCE,Blocks.CHEST.defaultBlockState(),3);world.setBlock(SUPPLY,Blocks.CHEST.defaultBlockState(),3);chest(SOURCE).setItem(0,gold(7));chest(SOURCE).setChanged();chest(SUPPLY).setItem(0,new ItemStack(Items.CHEST));chest(SUPPLY).setItem(1,gold(20));chest(SUPPLY).setChanged();source=chest(SOURCE).saveWithFullMetadata(world.registryAccess());beforeSupply=chest(SUPPLY).saveWithFullMetadata(world.registryAccess());root=(NativeCopyControllerEntity)world.getBlockEntity(ROOT);actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(ROOT.getX()+.5,ROOT.getY()+1,ROOT.getZ()-2);need(root.configure(actor,new CopySettings(1,0,0,ChannelList.EMPTY,false)),"Source-style settings admission");if(phase().equals("crash"))world.getServer().saveEverything(true,true,true);
        NativeCopyService.fault=(header,target)->{if(!target.pos.equals(SUPPLY))return;armed++;need(NativeCellTransactions.reservedBy(world,header,SOURCE),"exact callback Header may observe its own live reservation");var copiedHeader=new NativeCellTransactions.Header(header.operation(),header.family(),header.root(),header.owner(),header.actor(),header.creative());need(!NativeCellTransactions.reservedBy(world,copiedHeader,SOURCE)&&!NativeCellTransactions.reservedBy(world,header,ROOT.above(8)),"copied Headers and positions outside the receipt have no own reservation exemption");need(!world.setBlock(SOURCE,Blocks.EMERALD_BLOCK.defaultBlockState(),3),"read-only reservation observation never admits a source write");need(NativeTransferHolds.blocked(world,SUPPLY)&&NativeTransferHolds.blocked(world,SOURCE)&&NativeTransferHolds.blocked(world,TARGET),"all source, output and material cells held during armed material publication");need(chest(SUPPLY).getItem(0).isEmpty()&&ItemStack.matches(chest(SUPPLY).getItem(1),gold(13))&&world.getBlockState(TARGET).isAir(),"exact materials withdrawn before output publication");if(phase().equals("crash")){need(!new net.minecraft.world.level.ChunkPos(SUPPLY).equals(new net.minecraft.world.level.ChunkPos(TARGET)),"partial save genuinely excludes output chunk");world.noSave=true;var chunk=new net.minecraft.world.level.ChunkPos(SUPPLY);var loaded=world.getChunkSource().getChunkNow(chunk.x,chunk.z);world.getChunkSource().chunkMap.write(chunk,net.minecraft.world.level.chunk.storage.ChunkSerializer.write(world,loaded)).thenCompose(ignored->((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true)).whenComplete((ignored,error)->{if(error!=null){error.printStackTrace();System.out.flush();Runtime.getRuntime().halt(2);}System.out.println("[vandorlabs][copy-runtime] crash PASS checks="+checks+" afterMaterialWithdrawal/sourceOnlyCrossChunkSave/actualAsyncARMED/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);});throw new IllegalStateException("Awaiting deliberate abrupt Copy withdrawal checkpoint");}if(caught++==0)throw new IllegalStateException("Expected Copy withdrawal fault");};
    }catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!enabled()||world==null)return;try{ticks++;if(world.noSave&&phase().equals("crash")){need(world.getBlockState(TARGET).isAir(),"suspended crash cannot install output while source save is pending");return;}need(ticks-stageTick<250,"bounded asynchronous phase");
        if(stage==0&&ticks>=3){root.request(actor);need(root.busy(),"accepted copy remains queued while disk preparation is pending");stage=1;stageTick=ticks;return;}
        if(stage==1&&!root.busy()){need(armed==1&&caught>=1,"caught failure followed real durable ARMED callback");need(world.getBlockState(TARGET).isAir()&&chest(SUPPLY).saveWithFullMetadata(world.registryAccess()).equals(beforeSupply),"rollback restores the exact backing chest and leaves output absent");need(chest(SOURCE).saveWithFullMetadata(world.registryAccess()).equals(source),"copy input remains its original private owner");root.request(actor);stage=2;stageTick=ticks;return;}
        if(stage==2&&!root.busy()){need(armed==2,"retry traverses a new durable journal");need(world.getBlockState(TARGET).is(Blocks.CHEST),"one physical copied chest published");var expected=source.copy();expected.putInt("x",TARGET.getX());expected.putInt("y",TARGET.getY());expected.putInt("z",TARGET.getZ());need(chest(TARGET).saveWithFullMetadata(world.registryAccess()).equals(expected),"copied chest keeps exact name, count and custom item components");need(chest(SUPPLY).getItem(0).isEmpty()&&ItemStack.matches(chest(SUPPLY).getItem(1),gold(13)),"successful retry pays one block item and seven exact component-bearing items once");need(chest(SOURCE).saveWithFullMetadata(world.registryAccess()).equals(source),"source private data unchanged after successful copy");need(!NativeTransferHolds.active(world)&&!NativeCellTransactions.busy(world,ROOT,root.key()),"authority retired only after physical checkpoint");need(world.getEntitiesOfClass(ItemEntity.class,new AABB(ROOT).inflate(8)).isEmpty(),"no loose material duplicates");world.setBlock(INPUT,Blocks.AIR.defaultBlockState(),3);stage=3;stageTick=ticks;return;}
        if(stage==3&&ticks-stageTick>=3){need(root.input()==null&&root.output()==null,"a hole releases both saved Copy areas instead of leaving stale claims");world.setBlock(INPUT,NativeSurfaceBindings.BLOCK.defaultBlockState(),3);root.checkAreas(actor);need(root.input()!=null&&root.output()!=null,"repair permits an explicit paired-pad check");idleScans=root.topologyScans;idlePackets=root.packets;stage=4;stageTick=ticks;return;}
        if(stage==4&&ticks-stageTick>=25){need(root.topologyScans==idleScans,"settling cosmetic activity cannot trigger topology scans before="+idleScans+" after="+root.topologyScans);System.out.println("[vandorlabs][copy-runtime] settled counters scans="+root.topologyScans+" packetsBefore="+idlePackets+" packetsAfter="+root.packets);idleScans=root.topologyScans;idlePackets=root.packets;stage=5;stageTick=ticks;return;}
        if(stage==5&&ticks-stageTick>=20){need(root.topologyScans==idleScans&&root.packets==idlePackets,"settled Copy Controller idle scans="+idleScans+"->"+root.topologyScans+" packets="+idlePackets+"->"+root.packets);System.out.println("[vandorlabs][copy-runtime] PASS checks="+checks+" pairedPads/exactChestMaterials/realAsyncWithdrawal/caughtRollback/retry/privateComponents/holeRepair/idle");NativeCopyService.fault=null;world=null;event.getServer().halt(false);}
    }catch(Throwable failure){fail(failure);}}
    private static void read(ServerStartedEvent event){
        root=(NativeCopyControllerEntity)world.getBlockEntity(ROOT);need(root!=null&&!root.inert(),"physical Copy Controller retained after source-only chunk save");need(world.getBlockState(TARGET).isAir()&&world.getBlockEntity(TARGET)==null,"unpublished output remains empty after abrupt withdrawal");need(world.getBlockState(SUPPLY).is(Blocks.CHEST)&&chest(SUPPLY).getItem(0).is(Items.CHEST)&&chest(SUPPLY).getItem(0).getCount()==1&&ItemStack.matches(chest(SUPPLY).getItem(1),gold(20)),"exact material item plus original20 named/component gold restored once");int total=0;for(int slot=0;slot<chest(SUPPLY).getContainerSize();slot++)total+=chest(SUPPLY).getItem(slot).getCount();need(total==21,"no extra material inventory owners");need(world.getBlockState(SOURCE).is(Blocks.CHEST)&&ItemStack.matches(chest(SOURCE).getItem(0),gold(7)),"input retains its original seven component-bearing items");need(!root.busy()&&!NativeTransferHolds.active(world)&&!NativeCellTransactions.busy(world,ROOT,root.key()),"cold physical checkpoint and durable journal retirement complete before gameplay");need(world.getEntitiesOfClass(ItemEntity.class,new AABB(ROOT).inflate(8)).isEmpty(),"cold rollback leaves zero loose material copies");System.out.println("[vandorlabs][copy-runtime] read PASS checks="+checks+" oneOriginalSupply/inputRetained/outputAbsent/exactComponents/zeroLooseCopies/durableRetirement");world=null;event.getServer().halt(false);
    }
    private static void fail(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][copy-runtime] FAIL "+failure);NativeCopyService.fault=null;var server=world==null?net.neoforged.neoforge.server.ServerLifecycleHooks.getCurrentServer():world.getServer();world=null;if(server!=null)server.halt(false);}
    private NativeCopyRuntimeChecks(){}
}
